                    str(ROOT / 'tests' / GROUPS[group][0]), '--junitxml=' + str(out / f'{mode}-{group}.xml'),
                    '--basetemp=' + str(out / 'pytest-tmp' / (mode + '-' + group)),
                    '-o', 'cache_dir=' + str(out / 'pytest-cache' / (mode + '-' + group))], env)
            else:
                journal.run(mode + '-' + group, [*base, '--group', group], env)
