    r = _mm256_insertf128_ps(_mm256_castps128_ps256(_mm256_cvtpd_ps(r0)),_mm256_cvtpd_ps(r1),1);
    h = _mm256_insertf128_ps(_mm256_castps128_ps256(_mm256_cvtpd_ps(h0)),_mm256_cvtpd_ps(h1),1);
