             capabilities_sha256=sha(out/'toolchain-cmake-capabilities.log'),instances_sha256=sha(out/'toolchain-visual-studio-instances.log')))
        configure += ['-G',selection['generator'],'-A',selection['architecture'],'-T',selection['toolset'],
